1	/**
2	 * Shared CLI implementation for `pantoken-scaffold` and `create-pantoken-app` — same argv contract,
3	 * same interactive directory prompt, same post-scaffold instructions.
4	 *
5	 * @module
6	 * @alpha
7	 */
8	import { createInterface } from "node:readline/promises";
9	import { isScaffoldPlatform, scaffoldProject, SCAFFOLD_PLATFORMS } from "./index.ts";
10	
11	/** Options distinguishing the two bins that share this CLI. */
12	export interface ScaffoldCliOptions {
13	  /** How the invoking command reads in its own `--help` usage line, e.g. `"pantoken-scaffold"`. */
14	  usageCommand: string;
15	}
16	
17	/** Whether the directory prompt should run: no `--dir` flag was given, and stdin is an interactive TTY. */
18	export function shouldPromptForDir(
19	  dirFlag: string | undefined,
20	  isTTY: boolean | undefined,
21	): boolean {
22	  return dirFlag === undefined && isTTY === true;
23	}
24	
25	async function promptForDir(): Promise<string> {
26	  const rl = createInterface({ input: process.stdin, output: process.stdout });
27	  try {
28	    const answer = await rl.question("Project directory (. for current folder): ");
29	    return answer.trim() || ".";
30	  } finally {
31	    rl.close();
32	  }
33	}
34	
35	function parseArgs(argv: string[]): { help: boolean; platform?: string; dirFlag?: string } {
36	  let platform: string | undefined;
37	  let dirFlag: string | undefined;
38	
39	  for (let i = 0; i < argv.length; i += 1) {
40	    const arg = argv[i];
41	    if (arg === "--help" || arg === "-h") return { help: true, platform, dirFlag };
42	    if (arg === "--dir") {
43	      dirFlag = argv[i + 1];
44	      i += 1;
45	      continue;
46	    }
47	    if (!platform && !arg.startsWith("-")) {
48	      platform = arg;
49	      continue;
50	    }
51	    throw new Error(`Unknown option "${arg}".`);
52	  }
53	
54	  return { help: false, platform, dirFlag };
55	}
56	
57	/** Run the scaffold CLI end to end: parse argv, prompt if needed, scaffold, and print next steps. */
58	export async function runScaffoldCli(argv: string[], options: ScaffoldCliOptions): Promise<void> {
59	  const usage = () => `Usage: ${options.usageCommand} <${SCAFFOLD_PLATFORMS.join("|")}> [--dir .]`;
60	
61	  let parsed: { help: boolean; platform?: string; dirFlag?: string };
62	  try {
63	    parsed = parseArgs(argv);
64	  } catch (err) {
65	    console.error(err instanceof Error ? err.message : String(err));
66	    console.error(usage());
67	    process.exit(1);
68	  }
69	
70	  if (parsed.help) {
71	    console.log(usage());
72	    return;
73	  }
74	
75	  if (!parsed.platform || !isScaffoldPlatform(parsed.platform)) {
76	    console.error(`Unknown platform "${parsed.platform ?? ""}".`);
77	    console.error(usage());
78	    process.exit(1);
79	  }
80	
81	  const dir = shouldPromptForDir(parsed.dirFlag, process.stdin.isTTY)
82	    ? await promptForDir()
83	    : (parsed.dirFlag ?? ".");
84	
85	  try {
86	    const written = await scaffoldProject(parsed.platform, dir);
87	    for (const path of written) console.log(`✓ wrote ${path}`);
88	    console.log(`\nNext steps:\n  cd ${dir}\n  vp install   (or npm/pnpm/yarn/bun install)`);
89	  } catch (err) {
90	    console.error(`Error scaffolding project:`, err instanceof Error ? err.message : err);
91	    process.exit(1);
92	  }
93	}
