1	/**
2	 * `@pantoken/scaffold` — scaffold a starter project for a platform, with pantoken already
3	 * installed and wired in. Standalone; usable via `npx @pantoken/scaffold <platform>` without
4	 * `@pantoken/ai`.
5	 *
6	 * Powered by Bingo presets: each platform exports a preset that defines its scaffold structure.
7	 *
8	 * @module
9	 * @alpha
10	 */
11	import { mkdirSync, writeFileSync } from "node:fs";
12	import { dirname, join } from "node:path";
13	import { producePreset } from "bingo-stratum";
14	import { SCAFFOLDS } from "../generated/scaffolds.ts";
15	import { PRESET_LEDGER } from "../generated/preset-ledger.ts";
16	
17	/** A platform pantoken can scaffold a starter project for. */
18	export type ScaffoldPlatform = keyof typeof PRESET_LEDGER;
19	
20	/**
21	 * Every scaffoldable platform key (discovered from available presets).
22	 *
23	 * @example List available platforms
24	 * ```ts
25	 * import { SCAFFOLD_PLATFORMS } from "@pantoken/scaffold";
26	 *
27	 * console.log(SCAFFOLD_PLATFORMS); // → ["components", "react", "vue", "web-components"]
28	 * ```
29	 */
30	export const SCAFFOLD_PLATFORMS: readonly ScaffoldPlatform[] = Object.keys(
31	  PRESET_LEDGER,
32	) as readonly ScaffoldPlatform[];
33	
34	const SCAFFOLD_PLATFORM_SET = new Set<string>(SCAFFOLD_PLATFORMS);
35	
36	/** Alternate platform names accepted alongside the canonical preset key (e.g. the pre-Bingo `html`). */
37	const PLATFORM_ALIASES: Record<string, ScaffoldPlatform> = {
38	  html: "components",
39	};
40	
41	/** Whether `platform` is a known {@link ScaffoldPlatform} or one of its aliases (e.g. `html`). */
42	export function isScaffoldPlatform(platform: string): boolean {
43	  return SCAFFOLD_PLATFORM_SET.has(platform) || platform in PLATFORM_ALIASES;
44	}
45	
46	function resolveScaffoldPlatform(platform: string): ScaffoldPlatform {
47	  const resolved = PLATFORM_ALIASES[platform] ?? platform;
48	  if (SCAFFOLD_PLATFORM_SET.has(resolved)) return resolved as ScaffoldPlatform;
49	  throw new Error(
50	    `Unknown platform "${platform}". Expected one of: ${SCAFFOLD_PLATFORMS.join(", ")}.`,
51	  );
52	}
53	
54	/**
55	 * Scaffold a starter project for a platform, with pantoken already installed and wired in.
56	 *
57	 * @param platform - A {@link ScaffoldPlatform}.
58	 * @param dir - The target directory (default `"."`). Its basename (or `"pantoken-app"` for `"."`)
59	 *   is substituted for `{{projectName}}` in the template files.
60	 * @returns The paths written.
61	 *
62	 * @example Scaffold a React starter
63	 * ```ts
64	 * import { scaffoldProject } from "@pantoken/scaffold";
65	 *
66	 * scaffoldProject("react", "./my-app");
67	 * ```
68	 */
69	export async function scaffoldProject(platform: string, dir = "."): Promise<string[]> {
70	  const resolvedPlatform = resolveScaffoldPlatform(platform);
71	  const projectName = dir === "." ? "pantoken-app" : (dir.split("/").pop() ?? "pantoken-app");
72	  const written: string[] = [];
73	
74	  // Get the preset for this platform
75	  const preset = PRESET_LEDGER[resolvedPlatform];
76	
77	  // Use Bingo stratum to render the preset with options
78	  try {
79	    const creation = producePreset(preset, {
80	      offline: true,
81	      options: { name: projectName },
82	    });
83	
84	    // Write the files created by the preset
85	    for (const [file, rawContent] of Object.entries(creation.files ?? {})) {
86	      const path = join(dir, file);
87	      mkdirSync(dirname(path), { recursive: true });
88	      // Handle both string and Buffer/ArrayBuffer content types
89	      const content =
90	        rawContent instanceof ArrayBuffer ? Buffer.from(rawContent) : (rawContent as string);
91	      writeFileSync(path, content);
92	      written.push(path);
93	    }
94	  } catch {
95	    // Preset threw — fall through to the legacy template system below.
96	  }
97	
98	  // Presets with no blocks yet (or a failed render) produce no files — fall back to the legacy
99	  // scaffold template system so every platform still scaffolds something.
100	  if (written.length === 0) {
101	    const templates = SCAFFOLDS[resolvedPlatform as keyof typeof SCAFFOLDS];
102	    if (templates) {
103	      for (const [file, content] of Object.entries(templates)) {
104	        const substituted = content.replaceAll("{{projectName}}", projectName);
105	        const path = join(dir, file);
106	        mkdirSync(dirname(path), { recursive: true });
107	        writeFileSync(path, substituted);
108	        written.push(path);
109	      }
110	    }
111	  }
112	
113	  return written;
114	}
