1	#!/usr/bin/env node
2	import {
3	  AGENT_TOOLS,
4	  SCAFFOLD_PLATFORMS,
5	  installAgentAssets,
6	  isScaffoldPlatform,
7	  scaffoldAndInit,
8	} from "../dist/index.mjs";
9	
10	const argv = process.argv.slice(2);
11	const ALL_TOOL_SET = new Set([...AGENT_TOOLS, "all"]);
12	const HELP_FLAGS = new Set(["--help", "-h"]);
13	
14	const usage = () =>
15	  `Usage:\n` +
16	  `  pantoken-ai init [--tool <${["all", ...AGENT_TOOLS].join("|")}>] [--dir .]\n` +
17	  `  pantoken-ai scaffold <${SCAFFOLD_PLATFORMS.join("|")}> [--dir .] [--tool <${["all", ...AGENT_TOOLS].join("|")}>]\n\n` +
18	  `Tools: all, ${AGENT_TOOLS.join(", ")}\n` +
19	  `Platforms: ${SCAFFOLD_PLATFORMS.join(", ")}\n\n` +
20	  `"scaffold" writes a starter project (via @pantoken/scaffold) and installs the agent assets\n` +
21	  `(via "init") into the same directory. Use "npx @pantoken/scaffold <platform>" directly if you\n` +
22	  `only want the starter project without the agent assets.`;
23	
24	const flag = (name) => {
25	  const i = argv.indexOf(`--${name}`);
26	  return i !== -1 ? argv[i + 1] : undefined;
27	};
28	
29	function printUsageAndExit(code) {
30	  if (code === 0) {
31	    console.log(usage());
32	  } else {
33	    console.error(usage());
34	  }
35	  process.exit(code);
36	}
37	
38	/** Prints an "unknown X" error plus usage, and exits 1, unless `value` is in `set`. */
39	function requireChoice(value, set, label) {
40	  if (!set.has(value)) {
41	    console.error(`Unknown ${label} "${value ?? ""}".`);
42	    console.error(usage());
43	    process.exit(1);
44	  }
45	}
46	
47	function runInit() {
48	  const tool = flag("tool") ?? "all";
49	  const dir = flag("dir") ?? ".";
50	  requireChoice(tool, ALL_TOOL_SET, "tool");
51	  const written = installAgentAssets(tool, dir);
52	  for (const path of written) console.log(`✓ wrote ${path}`);
53	}
54	
55	function resolvePlatform() {
56	  const platform = argv[1];
57	  if (!platform || !isScaffoldPlatform(platform)) {
58	    console.error(`Unknown platform "${platform ?? ""}".`);
59	    printUsageAndExit(1);
60	  }
61	  return platform;
62	}
63	
64	async function writeScaffold(platform, dir, tool) {
65	  const written = await scaffoldAndInit(platform, dir, tool);
66	  for (const path of written) console.log(`✓ wrote ${path}`);
67	  console.log(`\nNext: cd ${dir} && npm install (or pnpm/yarn/bun install)`);
68	}
69	
70	async function runScaffold() {
71	  const platform = resolvePlatform();
72	  const dir = flag("dir") ?? ".";
73	  const tool = flag("tool") ?? "all";
74	  requireChoice(tool, ALL_TOOL_SET, "tool");
75	  await writeScaffold(platform, dir, tool);
76	}
77	
78	const COMMANDS = {
79	  init: runInit,
80	  scaffold: runScaffold,
81	};
82	
83	async function main() {
84	  const command = argv[0];
85	  if (HELP_FLAGS.has(command)) printUsageAndExit(0);
86	
87	  const run = COMMANDS[command];
88	  if (!run) printUsageAndExit(1);
89	  await run();
90	}
91	
92	main().catch((err) => {
93	  console.error("Fatal error:", err);
94	  process.exit(1);
95	});
