1	/**
2	 * `@pantoken/ai` — consumer-facing agent assets for projects that *use* pantoken (not for
3	 * developing pantoken itself).
4	 *
5	 * It ships an `AGENTS.md`, an `llms.txt`, editor/agent rule files (Cursor, Copilot, Windsurf), and
6	 * Claude Code skills (`init-pantoken`, `scaffold-pantoken`), plus {@link installAgentAssets} /
7	 * {@link scaffoldAndInit} / the `pantoken-ai` CLI to drop them into a consumer repo at the
8	 * conventional paths.
9	 *
10	 * @module
11	 * @alpha
12	 */
13	import { mkdirSync, writeFileSync } from "node:fs";
14	import { dirname, join } from "node:path";
15	import { scaffoldProject } from "@pantoken/scaffold";
16	import { ASSETS } from "../generated/assets.ts";
17	
18	export { ASSETS } from "../generated/assets.ts";
19	export { SCAFFOLD_PLATFORMS, isScaffoldPlatform, scaffoldProject } from "@pantoken/scaffold";
20	export type { ScaffoldPlatform } from "@pantoken/scaffold";
21	
22	/**
23	 * The `AGENTS.md` content (consumer usage guide).
24	 *
25	 * @example Serve the guide from an app route
26	 * ```ts
27	 * import { AGENTS_MD } from "@pantoken/ai";
28	 *
29	 * export function GET() {
30	 *   return new Response(AGENTS_MD, { headers: { "Content-Type": "text/markdown" } });
31	 * }
32	 * ```
33	 */
34	export const AGENTS_MD: string = ASSETS.agents;
35	/**
36	 * The `llms.txt` content.
37	 *
38	 * @example Write it to disk yourself
39	 * ```ts
40	 * import { writeFileSync } from "node:fs";
41	 * import { LLMS_TXT } from "@pantoken/ai";
42	 *
43	 * writeFileSync("llms.txt", LLMS_TXT);
44	 * ```
45	 */
46	export const LLMS_TXT: string = ASSETS.llms;
47	
48	/** An agent/editor tool pantoken can install assets for. */
49	export type AgentTool = "agents" | "llms" | "cursor" | "copilot" | "windsurf" | "claude";
50	
51	interface AssetTarget {
52	  file: string;
53	  content: string;
54	}
55	
56	/** Where each tool's asset(s) are written, relative to the target directory. */
57	const TARGETS: Record<AgentTool, AssetTarget[]> = {
58	  agents: [{ file: "AGENTS.md", content: ASSETS.agents }],
59	  llms: [{ file: "llms.txt", content: ASSETS.llms }],
60	  cursor: [{ file: ".cursor/rules/pantoken.mdc", content: ASSETS.cursor }],
61	  copilot: [{ file: ".github/copilot-instructions.md", content: ASSETS.copilot }],
62	  windsurf: [{ file: ".windsurf/rules/pantoken.md", content: ASSETS.windsurf }],
63	  claude: [
64	    { file: ".claude/skills/init-pantoken/SKILL.md", content: ASSETS.initSkill },
65	    { file: ".claude/skills/scaffold-pantoken/SKILL.md", content: ASSETS.scaffoldSkill },
66	    { file: "AGENTS.md", content: ASSETS.agents },
67	  ],
68	};
69	
70	/**
71	 * Every installable tool key.
72	 *
73	 * @example Install each tool individually
74	 * ```ts
75	 * import { AGENT_TOOLS, installAgentAssets } from "@pantoken/ai";
76	 *
77	 * for (const tool of AGENT_TOOLS) installAgentAssets(tool, "./my-app");
78	 * ```
79	 */
80	export const AGENT_TOOLS: readonly AgentTool[] = Object.keys(TARGETS) as AgentTool[];
81	
82	const AGENT_TOOL_SET = new Set<string>(AGENT_TOOLS);
83	
84	function ensureAgentTool(tool: string): asserts tool is AgentTool {
85	  if (AGENT_TOOL_SET.has(tool)) return;
86	  throw new Error(`Unknown tool "${tool}". Expected one of: ${AGENT_TOOLS.join(", ")}.`);
87	}
88	
89	/**
90	 * Write pantoken's agent assets for a tool into a consumer repo.
91	 *
92	 * @param tool - A specific {@link AgentTool}, or `"all"` for every asset.
93	 * @param dir - The target directory (default `"."`).
94	 * @returns The paths written.
95	 *
96	 * @example Install one tool's assets into a repo
97	 * ```ts
98	 * import { installAgentAssets } from "@pantoken/ai";
99	 *
100	 * const written = installAgentAssets("cursor", "./my-app");
101	 * // → ["my-app/.cursor/rules/pantoken.mdc"]
102	 * ```
103	 *
104	 * @example Install every asset into the current directory
105	 * ```ts
106	 * import { installAgentAssets } from "@pantoken/ai";
107	 *
108	 * installAgentAssets("all");
109	 * // writes AGENTS.md, llms.txt, and the Cursor/Copilot/Windsurf/Claude assets
110	 * ```
111	 */
112	export function installAgentAssets(tool: AgentTool | "all", dir = "."): string[] {
113	  const tools =
114	    tool === "all" ? AGENT_TOOLS : ((ensureAgentTool(tool), [tool]) as readonly AgentTool[]);
115	  const written = new Set<string>();
116	  for (const t of tools) {
117	    for (const { file, content } of TARGETS[t]) {
118	      const path = join(dir, file);
119	      mkdirSync(dirname(path), { recursive: true });
120	      writeFileSync(path, content);
121	      written.add(path);
122	    }
123	  }
124	  return [...written];
125	}
126	
127	/**
128	 * Scaffold a starter project for a platform (via `@pantoken/scaffold`), and install pantoken's
129	 * agent assets (via {@link installAgentAssets}) into the same directory.
130	 *
131	 * @param platform - A {@link ScaffoldPlatform}.
132	 * @param dir - The target directory (default `"."`). Its basename (or `"pantoken-app"` for `"."`)
133	 *   is substituted for `{{projectName}}` in the scaffold's template files.
134	 * @param tool - Which agent tool's assets to install alongside the scaffold (default `"all"`).
135	 * @returns The paths written, scaffold files first.
136	 *
137	 * @example Scaffold a React starter with every agent asset installed
138	 * ```ts
139	 * import { scaffoldAndInit } from "@pantoken/ai";
140	 *
141	 * scaffoldAndInit("react", "./my-app");
142	 * ```
143	 */
144	export async function scaffoldAndInit(
145	  platform: string,
146	  dir = ".",
147	  tool: AgentTool | "all" = "all",
148	): Promise<string[]> {
149	  const scaffoldPaths = await scaffoldProject(platform, dir);
150	  const assetPaths = installAgentAssets(tool, dir);
151	  return [...scaffoldPaths, ...assetPaths];
152	}
153

1	import { execFileSync } from "node:child_process";
2	import { existsSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
3	import { tmpdir } from "node:os";
4	import { join } from "node:path";
5	import { afterEach, beforeEach, expect, test, vi } from "vite-plus/test";
6	import { runScaffoldCli, shouldPromptForDir } from "../src/cli.ts";
7	
8	function mktemp(): string {
9	  return mkdtempSync(join(tmpdir(), "pantoken-scaffold-cli-"));
10	}
11	
12	/** Thrown by the `process.exit` spy below, so an exiting code path surfaces as a rejected promise. */
13	class ProcessExitError extends Error {
14	  constructor(public code: number | string | null | undefined) {
15	    super(`process.exit(${code})`);
16	  }
17	}
18	
19	test("shouldPromptForDir only prompts when --dir is omitted on a TTY", () => {
20	  expect(shouldPromptForDir(undefined, true)).toBe(true);
21	  expect(shouldPromptForDir(undefined, false)).toBe(false);
22	  expect(shouldPromptForDir(undefined, undefined)).toBe(false);
23	  expect(shouldPromptForDir("./my-app", true)).toBe(false);
24	});
25	
26	const bin = new URL("../bin/pantoken-scaffold.mjs", import.meta.url).pathname;
27	
28	test("--help does not scaffold anything", () => {
29	  const output = execFileSync("node", [bin, "--help"], { encoding: "utf8" });
30	  expect(output).toContain("pantoken-scaffold");
31	});
32	
33	test("prints vp install as the preferred next step", () => {
34	  const dir = mktemp();
35	  const target = join(dir, "my-app");
36	  const output = execFileSync("node", [bin, "react", "--dir", target], { encoding: "utf8" });
37	  expect(output).toContain("vp install");
38	  expect(existsSync(join(target, "package.json"))).toBe(true);
39	});
40	
41	test("still substitutes projectName with the shared CLI", () => {
42	  const dir = mktemp();
43	  const target = join(dir, "my-app");
44	  execFileSync("node", [bin, "react", "--dir", target], { encoding: "utf8" });
45	  expect(readFileSync(join(target, "package.json"), "utf8")).toContain('"name": "my-app"');
46	});
47	
48	// The tests above only exercise the built bin as a black box (a child process, so it never
49	// contributes to this file's coverage). The tests below call `runScaffoldCli` directly.
50	
51	let logSpy: ReturnType<typeof vi.spyOn>;
52	let errSpy: ReturnType<typeof vi.spyOn>;
53	let exitSpy: ReturnType<typeof vi.spyOn>;
54	
55	beforeEach(() => {
56	  logSpy = vi.spyOn(console, "log").mockImplementation(() => undefined);
57	  errSpy = vi.spyOn(console, "error").mockImplementation(() => undefined);
58	  exitSpy = vi.spyOn(process, "exit").mockImplementation((code?: number | string | null) => {
59	    throw new ProcessExitError(code);
60	  });
61	});
62	
63	afterEach(() => {
64	  logSpy.mockRestore();
65	  errSpy.mockRestore();
66	  exitSpy.mockRestore();
67	});
68	
69	test("--help prints usage and returns without exiting", async () => {
70	  await runScaffoldCli(["--help"], { usageCommand: "pantoken-scaffold" });
71	  expect(logSpy).toHaveBeenCalledWith(expect.stringContaining("pantoken-scaffold"));
72	  expect(exitSpy).not.toHaveBeenCalled();
73	});
74	
75	test("rejects an unrecognized flag", async () => {
76	  await expect(runScaffoldCli(["--bogus"], { usageCommand: "pantoken-scaffold" })).rejects.toThrow(
77	    ProcessExitError,
78	  );
79	  expect(errSpy).toHaveBeenCalledWith('Unknown option "--bogus".');
80	});
81	
82	test("rejects a second positional argument", async () => {
83	  await expect(
84	    runScaffoldCli(["react", "extra"], { usageCommand: "pantoken-scaffold" }),
85	  ).rejects.toThrow(ProcessExitError);
86	  expect(errSpy).toHaveBeenCalledWith('Unknown option "extra".');
87	});
88	
89	test("rejects an unknown platform", async () => {
90	  await expect(
91	    runScaffoldCli(["not-a-real-platform"], { usageCommand: "pantoken-scaffold" }),
92	  ).rejects.toThrow(ProcessExitError);
93	  expect(errSpy).toHaveBeenCalledWith('Unknown platform "not-a-real-platform".');
94	});
95	
96	test("requires a platform argument", async () => {
97	  await expect(runScaffoldCli([], { usageCommand: "pantoken-scaffold" })).rejects.toThrow(
98	    ProcessExitError,
99	  );
100	  expect(errSpy).toHaveBeenCalledWith('Unknown platform "".');
101	});
102	
103	test("scaffolds and prints vp install when --dir is given", async () => {
104	  const dir = mktemp();
105	  const target = join(dir, "my-app");
106	  await runScaffoldCli(["react", "--dir", target], { usageCommand: "pantoken-scaffold" });
107	  expect(existsSync(join(target, "package.json"))).toBe(true);
108	  expect(logSpy).toHaveBeenCalledWith(expect.stringContaining("vp install"));
109	});
110	
111	test("prompts for a directory when --dir is omitted on a TTY", async () => {
112	  const dir = mktemp();
113	  const target = join(dir, "prompted-app");
114	  const question = vi.fn().mockResolvedValue(target);
115	  const close = vi.fn();
116	  vi.doMock("node:readline/promises", () => ({ createInterface: () => ({ question, close }) }));
